#include <vector>
#include <algorithm>

class Solution {
public:
    int longestResilientSubarray(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (n <= 1) return n;

        int left = 0, drops = 0, max_len = 1;
        for (int right = 1; right < n; ++right) {
            if (nums[right] < nums[right - 1]) drops++;

            while (drops > k) {
                if (nums[left + 1] < nums[left]) drops--;
                left++;
            }
            max_len = std::max(max_len, right - left + 1);
        }
        return max_len;
    }
};

class Solution {
    public int longestResilientSubarray(int[] nums, int k) {
        int n = nums.length;
        if (n <= 1) return n;

        int left = 0, drops = 0, maxLen = 1;
        for (int right = 1; right < n; right++) {
            if (nums[right] < nums[right - 1]) drops++;

            while (drops > k) {
                if (nums[left + 1] < nums[left]) drops--;
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

